function fixtureVisit(PDO $p,int $id,string $note='Finalized',bool $paid=true):void{
 $p->prepare("INSERT INTO Appointments(AppointmentID,PatientID,ClinicID,PhysicianID,AppointmentDate,Status,BookingFeePaid,BookingPaymentMethod,BookingFeeAmount) VALUES(?,1,1,11,CURDATE(),'Confirmed',?,'wallet',500)")->execute([$id,$paid?1:0]);
 $p->prepare("INSERT INTO Consultations(ConsultationID,ClinicID,AppointmentID,PatientID,DoctorID) VALUES(?,1,?,1,11)")->execute([$id,$id]);
 $p->prepare("INSERT INTO ConsultationVersions(ConsultationID,EditedByPhysicianID,RevisionNumber,ClinicalNotes,Status) VALUES(?,11,1,'Synthetic reviewed note',?)")->execute([$id,$note]);
 $p->prepare("INSERT INTO Queue(QueueID,ClinicID,AppointmentID,PhysicianID,QueueNumber,RegularNumber,Status) VALUES(?,1,?,11,?,?,'Serving')")->execute([$id,$id,$id,$id]);
 if($paid)$p->prepare("INSERT INTO WalletTransactions(PatientID,Type,Amount,BalanceAfter,RelatedAppointmentID) VALUES(1,'BookingPayment',500,1000,?)")->execute([$id]);
}
